MaterialTextureSetDefinition3D TerrainTextures(){const std::filesystem::path root=std::filesystem::path{AEVRYND_SOURCE_DIR}/"engine"/"assets"/"material-packs";MaterialTextureSetDefinition3D result;result.baseColorPath=root/"ambientcg/ground037/1k/Ground037_1K-JPG_Color.jpg";result.roughnessPath=root/"ambientcg/ground037/1k/Ground037_1K-JPG_Roughness.jpg";result.normalPath=root/"ambientcg/ground037/1k/Ground037_1K-JPG_NormalDX.jpg";result.maximumResolution=1024;result.additionalLayers[0]={root/"poly-haven/aerial_ground_rock/1k/base-color.jpg",root/"poly-haven/aerial_ground_rock/1k/roughness.jpg",root/"poly-haven/aerial_ground_rock/1k/normal-dx.jpg"};result.additionalLayers[1]={root/"poly-haven/rock_surface/1k/base-color.jpg",root/"poly-haven/rock_surface/1k/roughness.jpg",root/"poly-haven/rock_surface/1k/normal-dx.jpg"};return result;}
