        const std::uint32_t normal=PackNormalSnorm8({0,1,0}),color=PackColorRgba8({1,1,1,.55f});const std::array<Vertex3D,4> vertices={Vertex3D{-1,-1,.2f,normal,color,0,1},Vertex3D{-1,1,.8f,normal,color,0,0},Vertex3D{1,1,.8f,normal,color,1,0},Vertex3D{1,-1,.2f,normal,color,1,1}};const std::array<std::uint32_t,6> indices={0,1,2,0,2,3};const MeshHandle3D mesh=renderer.CreateMesh(vertices,indices);const MaterialTextureSetHandle3D textures=renderer.CreateMaterialTextureSet(TerrainTextures());if(!result&&(!mesh||!textures))result=6;
