        const std::size_t textureBytes=captured.residentTextureBytes;renderer.Resize(800,450);renderer.Render(draw,{.10f,.19f,.31f,1});renderer.WaitIdle();const RendererStats resized=renderer.GetStats();if(!result&&(resized.residentTextureBytes!=textureBytes||resized.residentMaterialTextureSets!=1))result=8;renderer.DestroyMaterialTextureSet(textures);renderer.DestroyMesh(mesh);renderer.WaitIdle();renderer.TrimTransientMemory();const RendererStats released=renderer.GetStats();if(!result&&(released.residentMaterialTextureSets||released.residentTextureBytes||released.residentMeshes))result=9;
